const e={161:{dayName:"Dia 161 — Segunda-feira",title:"Entrevista 1: Tell Me About Yourself",focus:"Dominar a apresentação pessoal de 60 segundos.",vocab:[{en:"Applicant",pt:"Candidato"},{en:"Position",pt:"Vaga / Cargo"},{en:"Experience",pt:"Experiência"},{en:"Background",pt:"Formação / Histórico"},{en:"Skills",pt:"Habilidades"},{en:"Strengths",pt:"Pontos fortes"},{en:"Relevant",pt:"Relevante"},{en:"Opportunity",pt:"Oportunidade"},{en:"Journey",pt:"Jornada"},{en:"Fluent",pt:"Fluente"}],grammar:{title:"A Apresentação de 60 Segundos",rule:"1) OPENING (present): I'm a developer with X years of experience. 2) EXPERIENCE (past): I have worked at... I started with... 3) SKILLS (present): I can... I'm good at... 4) GOAL (future): I am looking for an opportunity to grow and contribute.",table:[{form:"Abertura",example:"I'm a developer with five years of experience.",pt:"Sou desenvolvedor com cinco anos de experiência."},{form:"Experiência",example:"I have worked with backend systems since 2021.",pt:"Trabalho com sistemas backend desde 2021."},{form:"Objetivo",example:"I am looking for a position where I can grow.",pt:"Procuro uma vaga onde eu possa crescer."}]},reading:{title:"The First Question",text:"Every interview starts the same: 'Tell me about yourself.' I have practiced this answer many times. My opening: 'I'm a software developer with four years of experience.' Then I share my background: 'I started with web development, and since then, I have specialized in backend systems.' My skills: 'I can build reliable APIs, and I'm good at solving performance problems.' My goal: 'I am looking for a position where I can contribute and grow.' Short, clear, and complete.",translation:"Toda entrevista começa igual: 'Fale sobre você.' Pratiquei essa resposta muitas vezes. Minha abertura: 'Sou desenvolvedor de software com quatro anos de experiência.' Depois compartilho minha formação: 'Comecei com desenvolvimento web e, desde então, me especializei em sistemas backend.' Minhas habilidades: 'Posso construir APIs confiáveis e sou bom em resolver problemas de performance.' Meu objetivo: 'Procuro uma posição onde possa contribuir e crescer.' Curto, claro e completo."},quiz:[{q:"Abertura:",options:["I'm a developer with four years of experience.","I am developer since four years.","Me developer, four years."],ans:"I'm a developer with four years of experience."},{q:"Formação:",options:["I have specialized in backend since then.","I specialized in backend since then.","I am specialize backend."],ans:"I have specialized in backend since then."},{q:"Objetivo:",options:["I am looking for a position where I can grow.","I look a position where I grow.","I am looking a position."],ans:"I am looking for a position where I can grow."}],chunks:[{en:"I'm a developer with four years of experience",pt:"sou desenvolvedor com quatro anos de experiência"},{en:"I have specialized in backend systems",pt:"me especializei em sistemas backend"},{en:"I am looking for a position where I can grow",pt:"procuro uma vaga onde eu possa crescer"}],listeningScript:"Tell me about yourself! I'm a developer with four years of experience. I started with web development. Since then, I have specialized in backend. I can build reliable APIs. I am looking for a position where I can grow. Short and strong!",speakingPrompt:"Grave sua apresentação de 60 segundos: 'I'm... I have worked... I can... I am looking for...'",lightReading:"The 60-second pitch is a mini-story: present (who), past (journey), perfect (growth), future (goal) — four moves, one breath.",journalPrompt:"Today is Day 161. I have mastered my self-introduction.",tip:"DICA DE ENTREVISTA: decore sua abertura com TEMPORIZADOR: 15s para o quem, 30s para a jornada, 15s para o objetivo. Grave 5 versões e escolha a melhor."},162:{dayName:"Dia 162 — Terça-feira",title:"Perguntas Comuns: Why Here? Responsibilities",focus:"Responder as perguntas clássicas com estrutura.",vocab:[{en:"Interviewer",pt:"Entrevistador"},{en:"Why",pt:"Por que"},{en:"Join",pt:"Entrar / Junta-se"},{en:"Company",pt:"Empresa"},{en:"Challenge",pt:"Desafio"},{en:"Responsible for",pt:"Responsável por"},{en:"Describe",pt:"Descrever"},{en:"Contribute",pt:"Contribuir"},{en:"Culture",pt:"Cultura"},{en:"Growth",pt:"Crescimento"}],grammar:{title:"Perguntas Clássicas e Respostas",rule:"WHY DO YOU WANT TO WORK HERE? = empresa (1 frase) + o que você entrega (1 frase) + crescimento (1 frase). WHAT ARE YOUR RESPONSIBILITIES? = verbo de ação + escopo: I am responsible for the backend of three products.",table:[{form:"Por que aqui?",example:"I admire your culture, and I can bring solid testing skills.",pt:"Admiro sua cultura e posso trazer sólidas habilidades de testes."},{form:"Responsabilidades",example:"I am responsible for the backend of three products.",pt:"Sou responsável pelo backend de três produtos."},{form:"Descreva seu dia",example:"I usually start with code review, then I focus on features.",pt:"Geralmente começo com revisão de código, depois foco em funcionalidades."}]},reading:{title:"The Second Question",text:"The second question is always: 'Why do you want to work here?' I have prepared a complete answer. First, the company: 'I admire your focus on quality and your international culture.' Then, my contribution: 'I can bring experience in performance and reliable testing.' Finally, growth: 'I am looking for a place where I can learn from senior engineers.' And about my responsibilities? 'I am responsible for the backend of two products, including APIs and databases.' Prepared answers remove the fear.",translation:"A segunda pergunta é sempre: 'Por que você quer trabalhar aqui?' Preparei uma resposta completa. Primeiro, a empresa: 'Admiro o foco de vocês em qualidade e a cultura internacional.' Depois, minha contribuição: 'Posso trazer experiência em performance e testes confiáveis.' Finalmente, crescimento: 'Procuro um lugar onde possa aprender com engenheiros seniores.' E sobre minhas responsabilidades? 'Sou responsável pelo backend de dois produtos, incluindo APIs e bancos de dados.' Respostas preparadas eliminam o medo."},quiz:[{q:"Por que aqui?",options:["I admire your culture, and I can bring solid skills.","Because I need money and the salary.","I don't know, maybe yes."],ans:"I admire your culture, and I can bring solid skills."},{q:"Responsabilidades:",options:["I am responsible for the backend of three products.","I responsible for the backend.","The backend is my responsibilities always."],ans:"I am responsible for the backend of three products."},{q:"Complete: 'I am looking for a place where I can ___ from seniors.'",options:["learn","learning","learned"],ans:"learn"}],chunks:[{en:"why do you want to work here?",pt:"por que você quer trabalhar aqui?"},{en:"I admire your culture and focus on quality",pt:"admiro sua cultura e o foco em qualidade"},{en:"I am responsible for the backend of three products",pt:"sou responsável pelo backend de três produtos"}],listeningScript:"Why here? I admire your culture and focus on quality. I can bring performance and testing skills. And I want to learn from senior engineers. My responsibilities? I am responsible for the backend of two products.",speakingPrompt:"Responda: 'Why do you want to work here? What are your responsibilities?'",lightReading:"Recruiters test preparation, not magic: every common question has a 3-part answer. If you can answer without thinking, you are ready.",journalPrompt:"Today is Day 162. I have prepared the classic questions.",tip:"DICA DE PREPARO: escreva as 10 perguntas mais comuns e suas respostas em 3 frases cada. Releia na véspera. 80% da entrevista vira rotina."},163:{dayName:"Dia 163 — Quarta-feira",title:"Método STAR (Situation, Task, Action, Result)",focus:"Contar conquistas em entrevistas com o método STAR.",vocab:[{en:"Situation",pt:"Situação"},{en:"Task",pt:"Tarefa"},{en:"Action",pt:"Ação"},{en:"Result",pt:"Resultado"},{en:"Specific",pt:"Específico"},{en:"Outcome",pt:"Desfecho"},{en:"Achieved",pt:"Alcançado"},{en:"Metrics",pt:"Métricas"},{en:"Story",pt:"História"},{en:"Detail",pt:"Detalhe"}],grammar:{title:"STAR para Histórias de Trabalho",rule:"S: contexto em 1 frase (past): We had a slow system. T: sua responsabilidade (past): I had to fix the performance. A: suas ações específicas (past): I profiled the code and changed the queries. R: resultado com número (past/perfect): Load time dropped by 40%.",table:[{form:"S",example:"We had a payment system with many errors.",pt:"Tínhamos um sistema de pagamentos com muitos erros."},{form:"T + A",example:"I had to reduce the failures, so I added logging and tests.",pt:"Eu tinha que reduzir as falhas, então adicionei logs e testes."},{form:"R",example:"The errors dropped by 50% in one month.",pt:"Os erros caíram 50% em um mês."}]},reading:{title:"The STAR Story",text:"Recruiters love stories. I use the STAR method: S — 'Last year, our system was slow and users complained.' T — 'I was responsible for fixing the performance.' A — 'I analyzed the database and rewrote the slow queries.' R — 'The page now loads 60% faster, and satisfaction has increased.' One story, four parts, all in the past. Since I started using STAR, my answers have become much stronger. Stories with numbers win.",translation:"Recrutadores amam histórias. Uso o método STAR: S — 'Ano passado, nosso sistema era lento e os usuários reclamavam.' T — 'Eu era responsável por corrigir a performance.' A — 'Analisei o banco e reescrevi as consultas lentas.' R — 'A página agora carrega 60% mais rápido e a satisfação aumentou.' Uma história, quatro partes, tudo no passado. Desde que comecei a usar STAR, minhas respostas ficaram muito mais fortes. Histórias com números vencem."},quiz:[{q:"Situação (S):",options:["Last year, our system was slow and users complained.","I fixed the system.","The system was fixed by someone."],ans:"Last year, our system was slow and users complained."},{q:"Tarefa (T):",options:["I was responsible for fixing the performance.","The performance was bad, sadly.","Performance, I fix it."],ans:"I was responsible for fixing the performance."},{q:"Resultado (R):",options:["The page now loads 60% faster.","The page is fast maybe.","Load 60% faster now."],ans:"The page now loads 60% faster."}],chunks:[{en:"last year, our system was slow",pt:"ano passado, nosso sistema era lento"},{en:"I analyzed the database and rewrote the queries",pt:"analisei o banco e reescrevi as consultas"},{en:"the page now loads 60% faster",pt:"a página agora carrega 60% mais rápido"}],listeningScript:"My STAR story: S — our system was slow. T — I was responsible for performance. A — I rewrote the slow queries. R — the page loads 60% faster. Stories with numbers win!",speakingPrompt:"Conte 1 conquista com STAR: 'S — ... T — ... A — ... R — ...'",lightReading:"Every behavioral interview answer is a mini-report: context (S), scope (T), work (A), impact (R). Watch tech talks and you will see STAR everywhere.",journalPrompt:"Today is Day 163. I have prepared a STAR story.",tip:"DICA DE OURO: prepare 3 histórias STAR (sucesso, dificuldade, trabalho em equipe) e adapte a qualquer pergunta comportamental. São as mesmas 3 histórias do seu portfólio."},164:{dayName:"Dia 164 — Quinta-feira",title:"Pontos Fortes e Fracos (Strengths & Weaknesses)",focus:"Falar de fraquezas sem se prejudicar.",vocab:[{en:"Weakness",pt:"Fraqueza"},{en:"Strength",pt:"Ponto forte"},{en:"Honest",pt:"Honesto"},{en:"Improve",pt:"Melhorar"},{en:"Growing",pt:"Crescendo"},{en:"Feedback",pt:"Feedback"},{en:"Humble",pt:"Humilde"},{en:"Confident",pt:"Confiante"},{en:"Balance",pt:"Equilíbrio"},{en:"Commit",pt:"Comprometer-se"}],grammar:{title:"Fraqueza Bem Contada",rule:"NUNCA diga 'I have no weaknesses'. Padrão: 1) Fraqueza real leve (present): I can be too careful with details. 2) Contexto (past): Last year, I spent too long polishing. 3) Melhoria (perfect): Since then, I have learned to balance quality and speed. 4) Prova: I now use time-boxing.",table:[{form:"Fraqueza",example:"I can be too careful with details.",pt:"Posso ser detalhista demais."},{form:"Contexto",example:"Last year, I spent too long polishing one feature.",pt:"Ano passado, passei tempo demais polindo uma funcionalidade."},{form:"Melhoria",example:"Since then, I have learned to balance quality and speed.",pt:"Desde então, aprendi a equilibrar qualidade e velocidade."}]},reading:{title:"The Honest Answer",text:"The question arrived: 'What is your greatest weakness?' I smiled and used my structure. 'I can be too careful with details. Last year, I spent too much time polishing a single feature. Since then, I have learned to balance quality and speed. Now I use time-boxing, and my delivery has improved.' Then, my strengths: 'My greatest strength is debugging complex systems. Last month, I found a bug that the team had hunted for weeks.' Honest weakness, real improvement, proven strength.",translation:"A pergunta chegou: 'Qual é a sua maior fraqueza?' Sorri e usei minha estrutura. 'Posso ser detalhista demais. Ano passado, passei tempo demais polindo uma única funcionalidade. Desde então, aprendi a equilibrar qualidade e velocidade. Agora uso time-boxing, e minha entrega melhorou.' Depois, meus pontos fortes: 'Meu maior ponto forte é depurar sistemas complexos. Mês passado, encontrei um bug que a equipe caçava há semanas.' Fraqueza honesta, melhoria real, força comprovada."},quiz:[{q:"Nunca diga:",options:["I have no weaknesses.","I can be too careful with details.","I used to struggle with public speaking."],ans:"I have no weaknesses."},{q:"Melhoria:",options:["Since then, I have learned to balance quality and speed.","Since then, I learned to balance maybe.","I am learning it yesterday."],ans:"Since then, I have learned to balance quality and speed."},{q:"Complete: 'Last month, I ___ a bug the team had hunted for weeks.'",options:["found","find","finding"],ans:"found"}],chunks:[{en:"I can be too careful with details",pt:"posso ser detalhista demais"},{en:"since then, I have learned to balance quality and speed",pt:"desde então, aprendi a equilibrar qualidade e velocidade"},{en:"my greatest strength is debugging complex systems",pt:"meu maior ponto forte é depurar sistemas complexos"}],listeningScript:"My weakness? I can be too careful with details. Last year, I spent too long polishing. Since then, I have learned to balance quality and speed. My strength? Debugging complex systems. Honest and strong!",speakingPrompt:"Fale de 1 fraqueza (com melhoria) e 2 forças (com prova).",lightReading:"Companies value self-awareness: the weakness question tests honesty plus growth. A weakness with a system (time-boxing) is worth more than a fake perfection.",journalPrompt:"Today is Day 164. I have prepared my strengths and weaknesses.",tip:"DICA DE PADRÃO: fraqueza REAL, mas leve; melhoria com EVIDÊNCIA; nunca 'perfeccionismo puro'. Se a fraqueza for algo essencial à vaga, escolha outra."},165:{dayName:"Dia 165 — Sexta-feira",title:"Negociação Salarial (Salary Negotiation)",focus:"Negociar salário com frases profissionais.",vocab:[{en:"Salary",pt:"Salário"},{en:"Negotiate",pt:"Negociar"},{en:"Offer",pt:"Oferta"},{en:"Range",pt:"Faixa"},{en:"Research",pt:"Pesquisa"},{en:"Market",pt:"Mercado"},{en:"Benefits",pt:"Benefícios"},{en:"Flexible",pt:"Flexível"},{en:"Counter-offer",pt:"Contraproposta"},{en:"Comfortable",pt:"Confortável"}],grammar:{title:"Frases de Negociação",rule:"1) PESQUISA: Based on my research, the market range is... 2) PERGUNTA: Is the offer flexible? 3) CONTRA: I was expecting around... 4) FECHAMENTO: If the package includes benefits, I can accept... NUNCA aceite ou recuse no mesmo dia.",table:[{form:"Pesquisa",example:"Based on my research, the market range is 8-10k.",pt:"Com base na minha pesquisa, a faixa de mercado é 8-10k."},{form:"Pergunta",example:"Is the salary flexible, or is it fixed?",pt:"O salário é flexível ou é fixo?"},{form:"Contraproposta",example:"If the package includes bonuses, I can accept.",pt:"Se o pacote incluir bônus, posso aceitar."}]},reading:{title:"The Negotiation",text:"The offer arrived: 9k with great benefits. I didn't answer immediately. The next day, I asked politely: 'Thank you for the offer. Based on my research, the market range for this position is 9-11k. Is the salary flexible?' The recruiter said they could go to 10k. I answered: 'If the package includes the annual bonus, I can accept 10k.' They agreed. I have learned that negotiation is a conversation, not a fight. Prepared numbers change everything.",translation:"A oferta chegou: 9k com ótimos benefícios. Não respondi imediatamente. No dia seguinte, perguntei educadamente: 'Obrigado pela oferta. Com base na minha pesquisa, a faixa de mercado para essa vaga é 9-11k. O salário é flexível?' O recrutador disse que podiam chegar a 10k. Respondi: 'Se o pacote incluir o bônus anual, posso aceitar 10k.' Eles concordaram. Aprendi que negociação é uma conversa, não uma briga. Números preparados mudam tudo."},quiz:[{q:"Pesquisa:",options:["Based on my research, the market range is 9-11k.","I think salary is 9k.","Market says 9k I guess."],ans:"Based on my research, the market range is 9-11k."},{q:"Pergunta:",options:["Is the salary flexible?","The salary is flexible yes?","Flexible salary, is it?"],ans:"Is the salary flexible?"},{q:"Complete: 'If the package ___ the annual bonus, I can accept.'",options:["includes","include","including"],ans:"includes"}],chunks:[{en:"based on my research, the market range is 9-11k",pt:"com base na minha pesquisa, a faixa de mercado é 9-11k"},{en:"is the salary flexible?",pt:"o salário é flexível?"},{en:"if the package includes bonuses, I can accept",pt:"se o pacote incluir bônus, posso aceitar"}],listeningScript:"The negotiation! I asked: based on my research, the range is 9-11k. Is it flexible? They offered 10k. I said: if it includes the bonus, I accept. Negotiation is a conversation, not a fight!",speakingPrompt:"Simule uma negociação: 'Based on my research... Is the offer flexible? If... I can accept.'",lightReading:"Salary surveys and market reports give you the passive voice of negotiation: 'The average is...', 'The range is defined by the market' — research is your best ally.",journalPrompt:"Today is Day 165. I have practiced salary negotiation.",tip:"DICA DE OURO: nunca diga seu salário atual primeiro. Responda: 'I can share my expectations: based on my research...' — o número da PESQUISA, não o do passado."},166:{dayName:"Dia 166 — Sábado",title:"Consolidação da Semana 24 + TESTE DE SÁBADO 24",focus:"Testar apresentação, STAR e negociação.",vocab:[{en:"Interview",pt:"Entrevista"},{en:"Preparation",pt:"Preparação"},{en:"Confident",pt:"Confiante"},{en:"Mock",pt:"Simulado"},{en:"Feedback",pt:"Feedback"},{en:"Improve",pt:"Melhorar"},{en:"Goal",pt:"Meta"},{en:"Ready",pt:"Pronto"},{en:"Review",pt:"Revisão"},{en:"Success",pt:"Sucesso"}],grammar:{title:"Resumo da Semana de Entrevistas",rule:"Apresentação: abertura (present) → jornada (past) → objetivo (future). Perguntas: empresa + contribuição + crescimento. Histórias: STAR (S-T-A-R). Fraqueza: real + melhoria (perfect) + prova. Negociação: pesquisa + pergunta + condição (if).",table:[{form:"Apresentação",example:"I'm a developer with four years of experience.",pt:"Sou desenvolvedor com quatro anos de experiência."},{form:"STAR",example:"We had a slow system, I rewrote the queries, and it got 60% faster.",pt:"Tínhamos um sistema lento, reescrevi as consultas e ficou 60% mais rápido."},{form:"Negociação",example:"Based on my research, the range is 9-11k.",pt:"Com base na minha pesquisa, a faixa é 9-11k."}]},reading:{title:"The Mock Interview",text:"Today I recorded a complete mock interview. First, my presentation: 'I'm a developer with four years of experience.' Then, a STAR story: 'Last year, the system was slow, so I analyzed the database and rewrote the queries. The result: 60% faster.' Then, my weakness: 'I can be too careful, but I have learned to balance quality and speed.' Finally, negotiation: 'Based on my research, I expect around 10k.' The recording showed me a big improvement since Monday. Preparation works.",translation:"Hoje gravei uma entrevista simulada completa. Primeiro, minha apresentação: 'Sou desenvolvedor com quatro anos de experiência.' Depois, uma história STAR: 'Ano passado, o sistema era lento, então analisei o banco e reescrevi as consultas. O resultado: 60% mais rápido.' Então, minha fraqueza: 'Posso ser detalhista demais, mas aprendi a equilibrar qualidade e velocidade.' Finalmente, negociação: 'Com base na minha pesquisa, espero em torno de 10k.' A gravação mostrou uma grande melhora desde segunda. Preparação funciona."},quiz:[{q:"Abertura:",options:["I'm a developer with four years of experience.","Developer four years I am.","I am four years experience."],ans:"I'm a developer with four years of experience."},{q:"STAR resultado:",options:["The result: 60% faster.","The result: faster 60.","Result: 60 fast."],ans:"The result: 60% faster."},{q:"Complete: 'Based on my research, I ___ around 10k.'",options:["expect","expected","expecting"],ans:"expect"}],chunks:[{en:"I'm a developer with four years of experience",pt:"sou desenvolvedor com quatro anos de experiência"},{en:"the result: 60% faster",pt:"o resultado: 60% mais rápido"},{en:"based on my research, I expect around 10k",pt:"com base na minha pesquisa, espero em torno de 10k"}],listeningScript:"Mock interview! Presentation: developer with four years. STAR: slow system, new queries, 60% faster. Weakness: careful, but balanced now. Salary: based on research, around 10k. I am improving every day!",speakingPrompt:"Grave seu Teste de Sábado: apresentação + 1 STAR + fraqueza + negociação (2 minutos).",lightReading:"Rehearsing is the difference between a good and a great candidate: the first recording is always the worst, and that is exactly why it exists.",journalPrompt:"Today is Day 166. I have passed my Saturday Test 24!",tip:"DICA DE GRAVAÇÃO: ouça sua gravação com FONES. Você ouvirá pausas e 'um' que não percebe ao vivo. Corrigir isso vale mais que 1 mês de curso."},167:{dayName:"Dia 167 — Domingo",title:"Revisão da Semana 24 & Imersão Leve",focus:"Assistir entrevistas reais em inglês com olhos técnicos.",vocab:[{en:"Real interview",pt:"Entrevista real"},{en:"Watch",pt:"Assistir"},{en:"Notice",pt:"Notar"},{en:"Confident",pt:"Confiante"},{en:"Professional",pt:"Profissional"},{en:"Body language",pt:"Linguagem corporal"},{en:"Natural",pt:"Natural"},{en:"Answer",pt:"Resposta"},{en:"Learn",pt:"Aprender"},{en:"Calm",pt:"Calmo"}],grammar:{title:"Checkpoint 167 — Olhar de Especialista",rule:"Ao assistir entrevistas reais, caça 3 coisas: 1) Frases que você já sabe (perfect/STAR/if). 2) Frases novas que faltam no seu arsenal. 3) Como eles falam de fraquezas e falhas. Anote 5 frases novas por entrevista.",table:[{form:"Já sei",example:"I have worked on similar projects.",pt:"Já trabalhei em projetos parecidos."},{form:"Nova",example:"I am happy to jump in and help.",pt:"Fico feliz em me envolver e ajudar."},{form:"Fraqueza",example:"I struggled with X at first, but I have improved.",pt:"Tive dificuldade com X no começo, mas melhorei."}]},reading:{title:"Learning From Others",text:"Today, I watched three real interviews in English. I noticed something: the best candidates speak slowly and use short sentences. They say things like: 'I have worked on similar projects.' 'That is a great question.' 'I can share an example.' They also pause before answering — it makes them look confident, not slow. I have collected ten new phrases for my next mock. If I watch one interview daily, my ear will become faster. Immersion is training too.",translation:"Hoje, assisti a três entrevistas reais em inglês. Notei algo: os melhores candidatos falam devagar e usam frases curtas. Eles dizem coisas como: 'Já trabalhei em projetos parecidos.' 'Essa é uma ótima pergunta.' 'Posso compartilhar um exemplo.' Também pausam antes de responder — isso os faz parecer confiantes, não lentos. Coletei dez frases novas para meu próximo simulado. Se eu assistir a uma entrevista por dia, meu ouvido ficará mais rápido. Imersão também é treino."},quiz:[{q:"Complete: 'I ___ worked on similar projects.'",options:["have","has","am"],ans:"have"},{q:"Complete: 'That is a great ___'",options:["question","asking","ask"],ans:"question"},{q:"Complete: 'I can ___ an example.'",options:["share","sharing","shared"],ans:"share"}],chunks:[{en:"I have worked on similar projects",pt:"já trabalhei em projetos parecidos"},{en:"that is a great question",pt:"essa é uma ótima pergunta"},{en:"I can share an example",pt:"posso compartilhar um exemplo"}],listeningScript:"Watch and learn! Best candidates speak slowly with short sentences: I have worked on similar projects. That is a great question. Pauses make you look confident. One interview daily!",speakingPrompt:"Conte 3 frases novas que aprendeu: 'I noticed... They say... I will use...'",lightReading:"Interview videos are free training data: each one gives you phrases, structure, and confidence calibration — ten minutes a day beats a grammar book.",journalPrompt:"Today is Day 167. I have learned from real interviews.",tip:"DICA DE CANAIS: procure 'mock interview software engineer' no YouTube. São entrevistas reais com feedback de verdade — melhor imersão que existe para entrevistas."},168:{dayName:"Dia 168 — Segunda-feira",title:"Entrevista Técnica: Explicando Código",focus:"Explicar código e arquitetura com clareza.",vocab:[{en:"Explain",pt:"Explicar"},{en:"Architecture",pt:"Arquitetura"},{en:"Function",pt:"Função"},{en:"Component",pt:"Componente"},{en:"Flow",pt:"Fluxo"},{en:"Database",pt:"Banco de dados"},{en:"API",pt:"API"},{en:"Tests",pt:"Testes"},{en:"Step",pt:"Passo"},{en:"Logic",pt:"Lógica"}],grammar:{title:"Linguagem de Código",rule:"Explique em ORDEM: 1) O que faz (present): This function handles payments. 2) Como flui (present): It receives the amount, then it validates the card. 3) Decisões (if): If the card is invalid, it returns an error. 4) Por que (past): I chose this approach because...",table:[{form:"O que faz",example:"This function handles the payment flow.",pt:"Esta função cuida do fluxo de pagamento."},{form:"Fluxo",example:"It receives the amount, then it validates the card.",pt:"Ela recebe o valor, depois valida o cartão."},{form:"Decisão",example:"If the card is invalid, it returns an error.",pt:"Se o cartão for inválido, ela retorna um erro."}]},reading:{title:"Walking Through My Code",text:"In a technical interview, I walked through my main function. 'This function handles the payment flow. First, it receives the amount and the card data. Then, it validates the card: if the card is invalid, it returns an error. After validation, it calls the payment API. Finally, it stores the result in the database.' The interviewer asked: 'Why did you choose this structure?' I answered: 'I have chosen it because it separates validation from the API call, which makes testing easier.' Explain like a story: input, process, output.",translation:"Numa entrevista técnica, expliquei minha função principal. 'Esta função cuida do fluxo de pagamento. Primeiro, ela recebe o valor e os dados do cartão. Depois, valida o cartão: se o cartão for inválido, retorna um erro. Após a validação, chama a API de pagamento. Finalmente, armazena o resultado no banco.' O entrevistador perguntou: 'Por que você escolheu essa estrutura?' Respondi: 'Escolhi porque ela separa a validação da chamada de API, o que facilita os testes.' Explique como história: entrada, processo, saída."},quiz:[{q:"O que faz:",options:["This function handles the payment flow.","The payment flow handles function.","Function payment flow this."],ans:"This function handles the payment flow."},{q:"Fluxo:",options:["It receives the amount, then it validates the card.","Receives amount, validates card, yes.","It receive and validate."],ans:"It receives the amount, then it validates the card."},{q:"Decisão:",options:["If the card is invalid, it returns an error.","If invalid card, error return.","When invalid, returned error."],ans:"If the card is invalid, it returns an error."}],chunks:[{en:"this function handles the payment flow",pt:"esta função cuida do fluxo de pagamento"},{en:"it receives the amount, then it validates the card",pt:"ela recebe o valor, depois valida o cartão"},{en:"if the card is invalid, it returns an error",pt:"se o cartão for inválido, ela retorna um erro"}],listeningScript:"Let me walk through my code! This function handles payments. It receives the amount, validates the card, calls the API, and stores the result. If the card is invalid, it returns an error. Simple flow!",speakingPrompt:"Explique seu código favorito: 'This... handles... It receives... Then... If... Finally...'",lightReading:"Explaining code is a story with input, process, and output: if you can narrate your functions like recipes, you will shine in technical interviews.",journalPrompt:"Today is Day 168. I have explained my code in English.",tip:"DICA DE ORDEM: SEMPRE comece pelo O QUE (1 frase), depois COMO, depois POR QUE. Nunca inverta. Entrevistadores decidem sua clareza nos primeiros 30 segundos."},169:{dayName:"Dia 169 — Terça-feira",title:"Perguntas Comportamentais (Behavioral)",focus:"Responder perguntas sobre conflitos, pressão e trabalho em equipe.",vocab:[{en:"Conflict",pt:"Conflito"},{en:"Teamwork",pt:"Trabalho em equipe"},{en:"Deadline",pt:"Prazo"},{en:"Pressure",pt:"Pressão"},{en:"Solve",pt:"Resolver"},{en:"Collaborate",pt:"Colaborar"},{en:"Communicate",pt:"Comunicar"},{en:"Respectful",pt:"Respeitoso"},{en:"Disagreement",pt:"Desentendimento"},{en:"Compromise",pt:"Acordo / Meio-termo"}],grammar:{title:"Behavioral: Tell Me About a Time...",rule:"Padrão de resposta: 1) SITUAÇÃO real (past): I remember a conflict about the architecture. 2) SUA AÇÃO (past): I asked for a private meeting and listened. 3) RESULTADO (past/perfect): We combined both ideas, and the project was delivered on time. A pergunta começa com: Tell me about a time when...",table:[{form:"Situação",example:"I remember a conflict about the architecture.",pt:"Lembro de um conflito sobre a arquitetura."},{form:"Ação",example:"I asked for a private meeting and listened first.",pt:"Pedi uma reunião privada e ouvi primeiro."},{form:"Resultado",example:"We combined both ideas and delivered on time.",pt:"Combinamos as duas ideias e entregamos no prazo."}]},reading:{title:"The Conflict",text:"The interviewer asked: 'Tell me about a time you faced a conflict.' I remembered the architecture debate. 'We had a disagreement about the new architecture. I asked for a private meeting and listened to my colleague first. Then, I explained my view with examples. We decided to test both approaches with a small prototype. The tests showed that a hybrid solution worked better. We shipped on time, and the team became closer.' Behavioral answers are just STAR stories about people.",translation:"O entrevistador perguntou: 'Conte sobre uma vez em que enfrentou um conflito.' Lembrei do debate da arquitetura. 'Tivemos um desentendimento sobre a nova arquitetura. Pedi uma reunião privada e ouvi meu colega primeiro. Depois, expliquei minha visão com exemplos. Decidimos testar as duas abordagens com um pequeno protótipo. Os testes mostraram que uma solução híbrida funcionava melhor. Entregamos no prazo e o time ficou mais unido.' Respostas comportamentais são só histórias STAR sobre pessoas."},quiz:[{q:"Situação:",options:["We had a disagreement about the architecture.","There is a disagreement always.","Disagreement architecture we had about."],ans:"We had a disagreement about the architecture."},{q:"Ação:",options:["I asked for a private meeting and listened first.","I asked meeting and first.","I listen and asked for meeting."],ans:"I asked for a private meeting and listened first."},{q:"Complete: 'We shipped on time, and the team ___ closer.'",options:["became","become","becoming"],ans:"became"}],chunks:[{en:"tell me about a time you faced a conflict",pt:"conte sobre uma vez em que enfrentou um conflito"},{en:"I asked for a private meeting and listened first",pt:"pedi uma reunião privada e ouvi primeiro"},{en:"we shipped on time, and the team became closer",pt:"entregamos no prazo e o time ficou mais unido"}],listeningScript:"A conflict story: we disagreed about the architecture. I asked for a private meeting and listened first. We tested both ideas. The hybrid worked. We shipped on time and became closer!",speakingPrompt:"Conte 1 conflito com a estrutura: situação + sua ação + resultado.",lightReading:"Conflict is a feature of good teams: interviews look for listeners who test ideas — 'I listened first' is the most powerful phrase in behavioral answers.",journalPrompt:"Today is Day 169. I have prepared behavioral stories.",tip:"DICA DE CONFLITO: a palavra mágica é LISTEN. Comece sempre: 'I listened first.' Entrevistadores querem candidatos que escutam antes de discutir."},170:{dayName:"Dia 170 — Quarta-feira",title:"Simulado 1: Entrevista Completa",focus:"Executar uma entrevista simulada completa de 15 minutos.",vocab:[{en:"Simulate",pt:"Simular"},{en:"Role",pt:"Papel"},{en:"Interviewer",pt:"Entrevistador"},{en:"Answer",pt:"Responder"},{en:"Pause",pt:"Pausa"},{en:"Rehearse",pt:"Ensaiorar"},{en:"Record",pt:"Gravar"},{en:"Review",pt:"Revisar"},{en:"Nerves",pt:"Nervosismo"},{en:"Calm",pt:"Calmo"}],grammar:{title:"Fluxo da Entrevista Simulada",rule:"15 minutos: 1) Apresentação (1 min). 2) Perguntas clássicas (5 min): why here, responsibilities, weaknesses. 3) STAR stories (5 min): sucesso, conflito, falha. 4) Perguntas do candidato (2 min). 5) Fechamento (1 min): 'Thank you for the opportunity.'",table:[{form:"Abertura",example:"Thank you for this opportunity. Let me introduce myself.",pt:"Obrigado pela oportunidade. Deixe-me me apresentar."},{form:"Meio",example:"I can share an example of that with numbers.",pt:"Posso compartilhar um exemplo disso com números."},{form:"Fechamento",example:"Thank you. When can I expect the next steps?",pt:"Obrigado. Quando posso esperar os próximos passos?"}]},reading:{title:"The Full Rehearsal",text:"Today was my full rehearsal. I set my phone to record and started. 'Thank you for this opportunity. I'm a developer with four years of experience.' I answered ten questions, including the difficult ones. When I didn't know the answer, I said: 'That is a great question. Let me think for a second.' I paused, organized my thoughts, and answered. In the end, I asked my questions and closed: 'Thank you very much. I am excited about this position.' The recording is my feedback. Every rehearsal makes the real interview easier.",translation:"Hoje foi meu ensaio completo. Configurei o celular para gravar e comecei. 'Obrigado pela oportunidade. Sou desenvolvedor com quatro anos de experiência.' Respondi dez perguntas, incluindo as difíceis. Quando não sabia a resposta, disse: 'Essa é uma ótima pergunta. Deixe-me pensar por um segundo.' Pausei, organizei os pensamentos e respondi. No fim, fiz minhas perguntas e fechei: 'Muito obrigado. Estou animado com essa vaga.' A gravação é meu feedback. Cada ensaio torna a entrevista real mais fácil."},quiz:[{q:"Abertura:",options:["Thank you for this opportunity. Let me introduce myself.","Opportunity thanks, I introduce.","Thanks, let me intro myself now."],ans:"Thank you for this opportunity. Let me introduce myself."},{q:"Ganhando tempo:",options:["That is a great question. Let me think for a second.","I don't know, next question.","Hmm, what?"],ans:"That is a great question. Let me think for a second."},{q:"Complete: 'When can I ___ the next steps?'",options:["expect","expected","expecting"],ans:"expect"}],chunks:[{en:"thank you for this opportunity",pt:"obrigado pela oportunidade"},{en:"let me think for a second",pt:"deixe-me pensar por um segundo"},{en:"when can I expect the next steps?",pt:"quando posso esperar os próximos passos?"}],listeningScript:"Full rehearsal! Thank you for this opportunity. I'm a developer with four years of experience. Difficult question? That is great, let me think. At the end: thank you. When can I expect the next steps?",speakingPrompt:"Grave a entrevista completa: apresentação + 10 perguntas + fechamento.",lightReading:"Rehearsal is deliberate practice: recording yourself turns every mistake into a lesson, and every lesson into a stronger answer for the real day.",journalPrompt:"Today is Day 170. I have completed my first full mock.",tip:"DICA DE NERVOS: quando não souber, use a frase honesta: 'That is a great question. Let me think for a second.' Pausa organizada = confiança. Nunca fale só para preencher o silêncio."},171:{dayName:"Dia 171 — Quinta-feira",title:"Perguntas do Candidato (Asking Questions)",focus:"Fazer perguntas inteligentes ao entrevistador.",vocab:[{en:"Ask",pt:"Perguntar"},{en:"Team",pt:"Equipe"},{en:"Product",pt:"Produto"},{en:"Roadmap",pt:"Roteiro de produto"},{en:"Culture",pt:"Cultura"},{en:"Remote",pt:"Remoto"},{en:"Expectations",pt:"Expectativas"},{en:"Growth",pt:"Crescimento"},{en:"Mentorship",pt:"Mentoria"},{en:"Transparent",pt:"Transparente"}],grammar:{title:"Perguntas Inteligentes",rule:"Ao final da entrevista, mostre interesse REAL: 1) TIME: Can you describe the team? 2) PRODUTO: What is the roadmap for the next six months? 3) CRESCIMENTO: How does feedback work here? 4) PROCESSO: What are the next steps? EVITE salário e férias na primeira entrevista.",table:[{form:"Time",example:"Can you describe the team I would join?",pt:"Pode descrever a equipe que eu entraria?"},{form:"Produto",example:"What is the roadmap for the next six months?",pt:"Qual é o roteiro para os próximos seis meses?"},{form:"Próximos passos",example:"What are the next steps in the process?",pt:"Quais são os próximos passos do processo?"}]},reading:{title:"The Smart Questions",text:"The interviewer asked: 'Do you have any questions for me?' This is my moment to shine. I asked: 'Can you describe the team I would join?' Then: 'What is the roadmap for the next six months?' Finally: 'How does feedback work here?' The interviewer smiled: 'Great questions. Our team is small and collaborative, and we do reviews every two weeks.' Asking questions shows interest. Candidates who ask nothing are forgotten. I have prepared five questions, and I will choose three.",translation:"O entrevistador perguntou: 'Você tem alguma pergunta para mim?' Este é meu momento de brilhar. Perguntei: 'Pode descrever a equipe que eu entraria?' Depois: 'Qual é o roteiro para os próximos seis meses?' Finalmente: 'Como funciona o feedback aqui?' O entrevistador sorriu: 'Ótimas perguntas. Nossa equipe é pequena e colaborativa, e fazemos reviews a cada duas semanas.' Fazer perguntas mostra interesse. Candidatos que não perguntam nada são esquecidos. Preparei cinco perguntas e escolherei três."},quiz:[{q:"Sobre o time:",options:["Can you describe the team I would join?","Team describe please.","The team is what?"],ans:"Can you describe the team I would join?"},{q:"Sobre o produto:",options:["What is the roadmap for the next six months?","Roadmap six months?","When roadmap?"],ans:"What is the roadmap for the next six months?"},{q:"Complete: 'What are the next ___ in the process?'",options:["steps","step","stepping"],ans:"steps"}],chunks:[{en:"can you describe the team I would join?",pt:"pode descrever a equipe que eu entraria?"},{en:"what is the roadmap for the next six months?",pt:"qual é o roteiro para os próximos seis meses?"},{en:"what are the next steps in the process?",pt:"quais são os próximos passos do processo?"}],listeningScript:"Questions for me? Can you describe the team? What is the roadmap for six months? How does feedback work? Asking questions shows interest. Ask smart questions!",speakingPrompt:"Pratique suas 5 perguntas: 'Can you...? What is...? How does...? What are...?'",lightReading:"Recruiters report that candidates who ask zero questions are rarely hired — the interview is a two-way evaluation, and your questions are your research.",journalPrompt:"Today is Day 171. I have prepared my questions for the interviewer.",tip:"DICA DE INTERESSE: pergunte sobre o TIME e o PRODUTO, não sobre o benefício. Interesse no trabalho vende mais que interesse no pacote."},172:{dayName:"Dia 172 — Sexta-feira",title:"Portfólio e Demo em Inglês",focus:"Apresentar um projeto completo em inglês.",vocab:[{en:"Portfolio",pt:"Portfólio"},{en:"Highlight",pt:"Destaque"},{en:"Demo",pt:"Demonstração"},{en:"Overview",pt:"Visão geral"},{en:"Architecture",pt:"Arquitetura"},{en:"Decision",pt:"Decisão"},{en:"Trade-off",pt:"Compensação / Escolha de projeto"},{en:"Walkthrough",pt:"Apresentação passo a passo"},{en:"User",pt:"Usuário"},{en:"Value",pt:"Valor"}],grammar:{title:"Estrutura de Demo Perfeita",rule:"1) OVERVIEW (present + passive): This app is built with React and Node. 2) ARQUITETURA (passive): The data is stored in PostgreSQL. 3) DECISÕES (past): I chose this because... 4) TRADE-OFFS (second conditional): If I had more time, I would add... 5) DEMO: As you can see, the user can...",table:[{form:"Overview",example:"This app is built with React and Node.",pt:"Este app é construído com React e Node."},{form:"Arquitetura",example:"The data is stored in PostgreSQL.",pt:"Os dados são armazenados no PostgreSQL."},{form:"Trade-off",example:"If I had more time, I would add offline mode.",pt:"Se eu tivesse mais tempo, adicionaria o modo offline."}]},reading:{title:"The Demo",text:"Time for the demo. 'This app is built with React and Node. The data is stored in PostgreSQL, and the API is hosted on a cloud server. I chose this architecture because it separates front and back ends. If I had more time, I would add offline mode and better tests. Now, the demo: as you can see, the user can create tasks, edit them, and track progress. The best feature is the weekly report: it was requested by real users.' One project, one story, all your English skills in action.",translation:"Hora da demo. 'Este app é construído com React e Node. Os dados são armazenados no PostgreSQL, e a API é hospedada num servidor na nuvem. Escolhi essa arquitetura porque ela separa front e back end. Se eu tivesse mais tempo, adicionaria o modo offline e melhores testes. Agora, a demo: como podem ver, o usuário pode criar tarefas, editá-las e acompanhar o progresso. A melhor funcionalidade é o relatório semanal: foi pedida por usuários reais.' Um projeto, uma história, todas as suas habilidades de inglês em ação."},quiz:[{q:"Overview:",options:["This app is built with React and Node.","This app builds with React.","Build app with React."],ans:"This app is built with React and Node."},{q:"Trade-off:",options:["If I had more time, I would add offline mode.","If I have time, I add offline.","If I had time, I will add."],ans:"If I had more time, I would add offline mode."},{q:"Complete: 'The data is ___ in PostgreSQL.'",options:["stored","store","storing"],ans:"stored"}],chunks:[{en:"this app is built with React and Node",pt:"este app é construído com React e Node"},{en:"the data is stored in PostgreSQL",pt:"os dados são armazenados no PostgreSQL"},{en:"if I had more time, I would add offline mode",pt:"se eu tivesse mais tempo, adicionaria o modo offline"}],listeningScript:"The demo! This app is built with React and Node. Data is stored in PostgreSQL. If I had more time, I would add offline mode. Now the demo: the user can create and edit tasks. Great story!",speakingPrompt:"Apresente seu projeto: overview + arquitetura + trade-off + demo (3 min).",lightReading:"Portfolio demos are full-stack English: present (overview), passive (architecture), past (decisions), second conditional (trade-offs) — every tense has a job.",journalPrompt:"Today is Day 172. I have presented my portfolio in English.",tip:"DICA DE DEMO: ensaie a demo inteira 3 vezes por dia. A parte de trade-offs ('If I had more time...') é a que mais impressiona — mostra visão de produto."},173:{dayName:"Dia 173 — Sábado",title:"Simulado 2: Autoanálise de Gravação",focus:"Analisar sua gravação e polir as respostas fracas.",vocab:[{en:"Record",pt:"Gravar"},{en:"Playback",pt:"Reprodução"},{en:"Analyze",pt:"Analisar"},{en:"Improvement",pt:"Melhoria"},{en:"Phrase",pt:"Frase"},{en:"Polish",pt:"Polidir"},{en:"Naturally",pt:"Naturalmente"},{en:"Repeated",pt:"Repetido"},{en:"Confident",pt:"Confiante"},{en:"Version",pt:"Versão"}],grammar:{title:"Autoanálise em 3 Passos",rule:"1) OUÇA sua gravação inteira (sem julgamento). 2) ANOTE os tropeços: palavras repetidas, 'um', pausas longas, frases traduzidas do português. 3) REESCREVA cada resposta fraca e regrave. Regra de ouro: cada gravação deve ser melhor que a anterior.",table:[{form:"Ouvir",example:"I listened to my mock with headphones.",pt:"Ouvi meu simulado com fones."},{form:"Anotar",example:"I noticed I said 'um' six times.",pt:"Notei que disse 'um' seis vezes."},{form:"Reescrever",example:"I have rewritten my weakest answer.",pt:"Reescrevi minha resposta mais fraca."}]},reading:{title:"The Analysis Session",text:"Today I listened to my mock interview. It was not perfect, and that is the point. I noticed three things: I said 'um' many times, one answer was too long, and I translated a sentence from Portuguese. My fixes: first, I practiced pausing instead of saying 'um'. Second, I cut my long answer from 2 minutes to 45 seconds. Third, I rewrote the translated sentence. The new version is much better. I have recorded four versions this week, and each one is stronger. Analysis is training too.",translation:"Hoje ouvi minha entrevista simulada. Não foi perfeita, e esse é o ponto. Notei três coisas: disse 'um' muitas vezes, uma resposta ficou longa demais e traduzi uma frase do português. Minhas correções: primeiro, pratiquei pausar em vez de dizer 'um'. Segundo, cortei minha resposta longa de 2 minutos para 45 segundos. Terceiro, reescrevi a frase traduzida. A nova versão está muito melhor. Gravei quatro versões esta semana, e cada uma é mais forte. Análise também é treino."},quiz:[{q:"Autoanálise:",options:["I listened to my mock with headphones.","I heard my mock maybe.","I listen mock headphones."],ans:"I listened to my mock with headphones."},{q:"Correção:",options:["I practiced pausing instead of saying 'um'.","I no say um.","Um I practiced."],ans:"I practiced pausing instead of saying 'um'."},{q:"Complete: 'Each recording ___ better than the last.'",options:["is","are","am"],ans:"is"}],chunks:[{en:"I listened to my mock with headphones",pt:"ouvi meu simulado com fones"},{en:"I practiced pausing instead of saying 'um'",pt:"pratiquei pausar em vez de dizer 'um'"},{en:"each recording is better than the last",pt:"cada gravação é melhor que a anterior"}],listeningScript:"Analysis time! I listened to my mock. Three problems: 'um', long answers, translated sentences. My fixes: pause instead of 'um', cut the long answers, rewrite translations. Version four is strong!",speakingPrompt:"Descreva sua autoanálise: 'I listened... I noticed... My fixes... The new version...'",lightReading:"Elite athletes watch their videos daily; interview candidates who analyze their recordings get the same edge — self-review is the highest-leverage practice.",journalPrompt:"Today is Day 173. I have analyzed and improved my mock.",tip:"DICA DE VERSÕES: grave sempre com o mesmo título (ex: mock_v5). Ver o número subir é uma prova física de evolução — motivação objetiva em arquivo."},174:{dayName:"Dia 174 — Domingo",title:"Revisão da Semana & Imersão Leve",focus:"Recarregar as energias com imersão leve.",vocab:[{en:"Rest",pt:"Descanso"},{en:"Podcast",pt:"Podcast"},{en:"Relax",pt:"Relaxar"},{en:"Episode",pt:"Episódio"},{en:"Fun",pt:"Diversão"},{en:"Balance",pt:"Equilíbrio"},{en:"Energy",pt:"Energia"},{en:"Fresh",pt:"Fresco / Revigorado"},{en:"Motivated",pt:"Motivado"},{en:"Final week",pt:"Semana final"}],grammar:{title:"Checkpoint 174 — Semana de Entrevistas Completa",rule:"Você já sabe: se apresentar (present/past/future), contar histórias (STAR), falar de fraquezas (perfect), negociar (if/conditional), explicar código (flow + if), perguntar e fechar. Falta a semana final: revisão total e teste B1.",table:[{form:"Já dominado",example:"I'm a developer with four years of experience.",pt:"Sou desenvolvedor com quatro anos de experiência."},{form:"Já dominado",example:"The page now loads 60% faster.",pt:"A página agora carrega 60% mais rápido."},{form:"Próximo passo",example:"The final test will be taken on Day 180.",pt:"O teste final será feito no Dia 180."}]},reading:{title:"The Calm Before the Final Week",text:"Today is my day of rest. I have practiced interviews all week, and my brain needs a break. I will listen to one fun podcast in English and watch a light series with subtitles. Tomorrow, the final week begins: complete review of grammar and the grand test. I have learned so much: 174 days of consistent practice. If I rest today, I will be strong tomorrow. Rest is part of the plan, not the enemy of the plan.",translation:"Hoje é meu dia de descanso. Pratiquei entrevistas a semana toda, e meu cérebro precisa de uma pausa. Vou ouvir um podcast divertido em inglês e assistir a uma série leve com legendas. Amanhã, a semana final começa: revisão completa da gramática e o grande teste. Aprendi tanto: 174 dias de prática constante. Se eu descansar hoje, estarei forte amanhã. Descanso faz parte do plano, não é inimigo do plano."},quiz:[{q:"Descanso:",options:["I will listen to a fun podcast in English.","I listen podcast fun maybe.","I will listening a podcast."],ans:"I will listen to a fun podcast in English."},{q:"Plano:",options:["If I rest today, I will be strong tomorrow.","If I rest today, I am strong yesterday.","If I will rest, I strong."],ans:"If I rest today, I will be strong tomorrow."},{q:"Complete: 'Rest is part of the ___, not the enemy.'",options:["plan","planned","planning"],ans:"plan"}],chunks:[{en:"my brain needs a break",pt:"meu cérebro precisa de uma pausa"},{en:"if I rest today, I will be strong tomorrow",pt:"se eu descansar hoje, estarei forte amanhã"},{en:"rest is part of the plan",pt:"descanso faz parte do plano"}],listeningScript:"Day of rest! I have practiced all week. Today: one fun podcast and a light series. Tomorrow, the final week begins. Rest is part of the plan. Strong tomorrow!",speakingPrompt:"Fale do seu descanso: 'Today I will... Tomorrow I will... Rest is part of the plan because...'",lightReading:"Recovery science is clear: the brain consolidates learning during rest — the best interview answers are built on calm, not on fatigue.",journalPrompt:"Today is Day 174. I have rested and prepared my energy.",tip:"DICA DE DESCANSO: no descanso, consuma inglês DIVERTIDO (série, podcast). O cérebro continua treinando o ouvido sem esforço — imersão leve é descanso ativo."},175:{dayName:"Dia 175 — Segunda-feira",title:"Revisão Final 1: Todos os Tempos",focus:"Mapa mental final dos tempos verbais.",vocab:[{en:"Review",pt:"Revisão"},{en:"Complete",pt:"Completo"},{en:"Timeline",pt:"Linha do tempo"},{en:"Anchor",pt:"Âncora"},{en:"Tense",pt:"Tempo verbal"},{en:"Form",pt:"Forma"},{en:"Action",pt:"Ação"},{en:"Habit",pt:"Hábito"},{en:"Finished",pt:"Concluído"},{en:"Ongoing",pt:"Em andamento"}],grammar:{title:"O Mapa dos Tempos",rule:"PRESENT = hábito/fato (I work). PAST = concluído com âncora (I worked yesterday). FUTURE = plano (I will work). PRESENT PERFECT = conexão com agora (I have worked here for years). CONTINUOUS = atividade em andamento (I have been working). Pergunta-chave: FINALIZADO + âncora = past; RELEVANTE AGORA = perfect.",table:[{form:"Passado com âncora",example:"I finished the project yesterday.",pt:"Terminei o projeto ontem."},{form:"Conexão com agora",example:"I have finished three projects this year.",pt:"Terminei três projetos este ano."},{form:"Atividade",example:"I have been working on the API all week.",pt:"Venho trabalhando na API a semana toda."}]},reading:{title:"The Time Map",text:"Final review time. I wrote my time map: present for habits ('I work with Node'), past for finished moments ('Last year, I built a payment system'), future for plans ('Next month, I will join a new team'), perfect for connections ('I have worked remotely for years'), and continuous for ongoing activity ('I have been studying English for 175 days'). The anchors are my compass: yesterday, last year, ago → past; this week, since, for → perfect; next month → future. One map, zero confusion.",translation:"Hora da revisão final. Escrevi meu mapa de tempos: presente para hábitos ('Trabalho com Node'), passado para momentos concluídos ('Ano passado, construí um sistema de pagamentos'), futuro para planos ('Mês que vem, entrarei num novo time'), perfect para conexões ('Trabalho remotamente há anos'), e continuous para atividades em andamento ('Venho estudando inglês há 175 dias'). As âncoras são minha bússola: yesterday, last year, ago → passado; this week, since, for → perfect; next month → futuro. Um mapa, zero confusão."},quiz:[{q:"Passado com âncora:",options:["I finished the project yesterday.","I have finished the project yesterday.","I finish the project yesterday."],ans:"I finished the project yesterday."},{q:"Perfect:",options:["I have finished three projects this year.","I finished three projects this year.","I finish three projects this year."],ans:"I have finished three projects this year."},{q:"Complete: 'I ___ been working on the API all week.'",options:["have","has","had"],ans:"have"}],chunks:[{en:"I finished the project yesterday",pt:"terminei o projeto ontem"},{en:"I have finished three projects this year",pt:"terminei três projetos este ano"},{en:"I have been working on the API all week",pt:"venho trabalhando na API a semana toda"}],listeningScript:"The time map! Past with anchor: I finished yesterday. Perfect: I have finished this year. Ongoing: I have been working all week. Future: I will join next month. Anchors are the compass!",speakingPrompt:"Fale sua linha do tempo: 'Last year, I... This year, I have... Next month, I will... I have been...'",lightReading:"Time anchors are grammar GPS: yesterday/last/ago point to past; this week/since/for point to perfect; next/tomorrow point to future — trust the anchors.",journalPrompt:"Today is Day 175. I have completed my time map.",tip:"DICA DO MAPA: desenhe a linha do tempo num papel com as âncoras. Cenas de filme: pin 3 memórias em cada tempo. Visualizar = memorizar."},176:{dayName:"Dia 176 — Terça-feira",title:"Revisão Final 2: Condicionais & Voz Passiva",focus:"Fechar condicionais e passiva com mapa final.",vocab:[{en:"Conditional",pt:"Condicional"},{en:"Passive",pt:"Passiva"},{en:"Active",pt:"Ativa"},{en:"Fact",pt:"Fato"},{en:"Real",pt:"Real"},{en:"Hypothetical",pt:"Hipotético"},{en:"Advice",pt:"Conselho"},{en:"Process",pt:"Processo"},{en:"Result",pt:"Resultado"},{en:"Voice",pt:"Voz"}],grammar:{title:"Mapa Final: Condicionais + Passiva",rule:"ZERO (fato): If you heat water, it boils. FIRST (real): If I get the job, I will move. SECOND (imaginário): If I were you, I would accept. PASSIVA (ação): The code is reviewed. ATIVA (autor): I review the code. Escolha pelo objetivo: fato, realidade, imaginação, ação ou autor.",table:[{form:"Zero",example:"If you don't test, bugs appear.",pt:"Se você não testa, bugs aparecem."},{form:"First",example:"If I get the job, I will move.",pt:"Se eu conseguir o emprego, vou me mudar."},{form:"Second + passiva",example:"If I were you, I would accept. The offer was sent.",pt:"Se eu fosse você, aceitaria. A oferta foi enviada."}]},reading:{title:"The Final Map",text:"Today I closed the grammar map. Zero conditional for truths: 'If you don't test, bugs appear.' First for real plans: 'If I get the job, I will move to Lisbon.' Second for dreams and advice: 'If I were you, I would accept the offer.' And the passive for processes: 'The code is reviewed before deployment; the offer was sent yesterday.' Active for responsibility: 'I reviewed the code myself.' I have practiced each one 100 times. Now they feel automatic. Grammar is finally my tool, not my fear.",translation:"Hoje fechei o mapa da gramática. Zero conditional para verdades: 'Se você não testa, bugs aparecem.' First para planos reais: 'Se eu conseguir o emprego, vou me mudar para Lisboa.' Second para sonhos e conselhos: 'Se eu fosse você, aceitaria a oferta.' E a passiva para processos: 'O código é revisado antes do deploy; a oferta foi enviada ontem.' Ativa para responsabilidade: 'Eu mesmo revisei o código.' Pratiquei cada um 100 vezes. Agora eles parecem automáticos. A gramática finalmente é minha ferramenta, não meu medo."},quiz:[{q:"Zero:",options:["If you don't test, bugs appear.","If you don't test, bugs will appear.","If you didn't test, bugs appear."],ans:"If you don't test, bugs appear."},{q:"Second:",options:["If I were you, I would accept the offer.","If I am you, I accept.","If I was you, I accept."],ans:"If I were you, I would accept the offer."},{q:"Complete: 'The offer ___ sent yesterday.'",options:["was","were","is"],ans:"was"}],chunks:[{en:"if you don't test, bugs appear",pt:"se você não testa, bugs aparecem"},{en:"if I were you, I would accept the offer",pt:"se eu fosse você, aceitaria a oferta"},{en:"the code is reviewed before deployment",pt:"o código é revisado antes do deploy"}],listeningScript:"The final map! Zero: if you don't test, bugs appear. First: if I get the job, I will move. Second: if I were you, I would accept. Passive: the offer was sent. Grammar is my tool now!",speakingPrompt:"Crie 3 frases por estrutura: zero, first, second, passiva.",lightReading:"Advanced users choose structure by intention: fact (zero), probability (first), imagination (second), focus on action (passive) — intention is the selector.",journalPrompt:"Today is Day 176. I have closed the grammar map.",tip:"DICA FINAL DE GRAMÁTICA: antes de falar, decida a INTENÇÃO: fato? probabilidade? sonho? processo? A intenção escolhe a estrutura — você só executa."},177:{dayName:"Dia 177 — Quarta-feira",title:"Maratona Final de Vocabulário",focus:"Recall ativo total dos chunks mais importantes.",vocab:[{en:"Marathon",pt:"Maratona"},{en:"Chunks",pt:"Pedaços de frase"},{en:"Recall",pt:"Recordação"},{en:"Automatic",pt:"Automático"},{en:"Solid",pt:"Sólido"},{en:"Vocabulary",pt:"Vocabulário"},{en:"Phrases",pt:"Frases"},{en:"Reflexes",pt:"Reflexos"},{en:"Mental",pt:"Mental"},{en:"Automaticity",pt:"Automaticidade"}],grammar:{title:"Técnica de Recall em Maratona",rule:"20 minutos de recall ATIVO: 1) EN → PT: ouça o chunk em inglês e diga o português. 2) PT → EN: o inverso, sem pensar. 3) Meta: 12 chunks por sessão saindo INSTANTANEAMENTE. Errou 2 segundos? Repita 5 vezes. A fluência é feita de reflexos.",table:[{form:"EN → PT",example:"I have been working on it → venho trabalhando nisso",pt:"reconhecer é o primeiro nível"},{form:"PT → EN",example:"se eu fosse você → if I were you",pt:"produzir é o segundo nível"},{form:"Instantâneo",example:"tell me about yourself → automático",pt:"reflexo é o nível final"}]},reading:{title:"The Recall Marathon",text:"Today was my vocabulary marathon. I reviewed the most powerful chunks of the entire journey. From the beginning: 'I have been studying English for 177 days.' From interviews: 'I'm a developer with four years of experience.' From tech: 'The code is reviewed before deployment.' From life: 'If I were you, I would accept.' I tested myself: English to Portuguese, then Portuguese to English. Twelve chunks per session, until each one felt automatic. My mouth is faster now. The marathon is tiring, but the reflexes are real.",translation:"Hoje foi minha maratona de vocabulário. Revisei os chunks mais poderosos de toda a jornada. Do começo: 'Venho estudando inglês há 177 dias.' Das entrevistas: 'Sou desenvolvedor com quatro anos de experiência.' Da tecnologia: 'O código é revisado antes do deploy.' Da vida: 'Se eu fosse você, aceitaria.' Testei a mim mesmo: inglês para português, depois português para inglês. Doze chunks por sessão, até cada um parecer automático. Minha boca está mais rápida agora. A maratona cansa, mas os reflexos são reais."},quiz:[{q:"PT → EN de 'se eu fosse você':",options:["if I were you","if I was you","if I am you"],ans:"if I were you"},{q:"EN → PT de 'the code is reviewed':",options:["o código é revisado","o código revisa","o código revisado"],ans:"o código é revisado"},{q:"Complete: 'I have been ___ English for 177 days.'",options:["studying","studied","study"],ans:"studying"}],chunks:[{en:"I have been studying English for 177 days",pt:"venho estudando inglês há 177 dias"},{en:"I'm a developer with four years of experience",pt:"sou desenvolvedor com quatro anos de experiência"},{en:"if I were you, I would accept",pt:"se eu fosse você, aceitaria"}],listeningScript:"Recall marathon! From the start: I have been studying for 177 days. From interviews: I'm a developer with four years. From tech: the code is reviewed before deployment. Twelve chunks, automatic reflexes!",speakingPrompt:"Teste-se: 12 chunks EN→PT e depois PT→EN, cronometrado.",lightReading:"Fluency is reflexes: the difference between 'translating' and 'speaking' is automaticity — chunks stored as one unit, retrieved as one unit.",journalPrompt:"Today is Day 177. I have completed the vocabulary marathon.",tip:"DICA DE REFLEXO: teste oral em voz ALTA. Ler mentalmente engana o cérebro; falar em voz alta constrói o músculo da pronúncia e o reflexo juntos."},178:{dayName:"Dia 178 — Quinta-feira",title:"Maratona Final de Listening",focus:"Escuta contínua em velocidade natural sem legendas.",vocab:[{en:"Speed",pt:"Velocidade"},{en:"Natural",pt:"Natural"},{en:"Accent",pt:"Sotaque"},{en:"Subtitles off",pt:"Legendas desligadas"},{en:"Concentration",pt:"Concentração"},{en:"Stamina",pt:"Resistência"},{en:"Comprehension",pt:"Compreensão"},{en:"Podcast",pt:"Podcast"},{en:"Native",pt:"Nativo"},{en:"Flow",pt:"Fluidez"}],grammar:{title:"Escuta Final: Protocolo 20 Minutos",rule:"1) Escolha 1 podcast tech em 1x (sem legendas). 2) Ouça 20 minutos SEGUIDOS, mesmo perdendo pedaços. 3) Ao final, resuma ORALMENTE em 3 frases (o tema, um detalhe, sua opinião). 4) Re-ouça os 3 minutos mais difíceis. A resistência de escuta também é treinável.",table:[{form:"Ouça",example:"I listened to a tech podcast for 20 minutes.",pt:"Ouvi um podcast tech por 20 minutos."},{form:"Resuma",example:"The episode was about AI for developers.",pt:"O episódio era sobre IA para desenvolvedores."},{form:"Re-ouça",example:"I repeated the hardest three minutes.",pt:"Repeti os três minutos mais difíceis."}]},reading:{title:"The Listening Marathon",text:"Final listening day. I chose a tech podcast about AI tools and listened for 20 minutes without subtitles. I understood maybe 85%: the flow, the opinions, the examples. Some words escaped me, but I kept going — the flow is more important than single words. After the episode, I summarized out loud: 'The episode was about AI for developers. They said small teams can use AI daily. I think the best part was the practical examples.' Then I re-listened to the hardest three minutes. Stamina: trained.",translation:"Dia final de escuta. Escolhi um podcast tech sobre ferramentas de IA e ouvi 20 minutos sem legendas. Entendi talvez 85%: o fluxo, as opiniões, os exemplos. Algumas palavras escaparam, mas continuei — o fluxo é mais importante que palavras isoladas. Depois do episódio, resumi em voz alta: 'O episódio era sobre IA para desenvolvedores. Eles disseram que times pequenos podem usar IA diariamente. Acho que a melhor parte foram os exemplos práticos.' Então re-ouvi os três minutos mais difíceis. Resistência: treinada."},quiz:[{q:"Protocolo:",options:["I listened for 20 minutes without subtitles.","I listen 20 minutes with subtitles.","I listened 20 minutes slow speed."],ans:"I listened for 20 minutes without subtitles."},{q:"Resumo oral:",options:["The episode was about AI for developers.","Podcast about AI yes.","Episode was AI developers about."],ans:"The episode was about AI for developers."},{q:"Complete: 'I ___ the hardest three minutes.'",options:["re-listened to","re-listen to","re-listening to"],ans:"re-listened to"}],chunks:[{en:"I listened for 20 minutes without subtitles",pt:"ouvi 20 minutos sem legendas"},{en:"the episode was about AI for developers",pt:"o episódio era sobre IA para desenvolvedores"},{en:"I re-listened to the hardest three minutes",pt:"re-ouvi os três minutos mais difíceis"}],listeningScript:"Listening marathon! Twenty minutes, no subtitles, natural speed. I understood the flow and the opinions. Then I summarized out loud. Then I repeated the hard parts. Stamina trained!",speakingPrompt:"Resuma o podcast em 3 frases: 'It was about... They said... I think...'",lightReading:"Listening stamina is built in blocks: 20 focused minutes daily beats 2 hours distractedly — the brain adapts to continuous flow faster than to isolated words.",journalPrompt:"Today is Day 178. I have completed the listening marathon.",tip:"DICA DE FLUXO: se perder 1 palavra, NÃO volte. Siga o fluxo. Voltar quebra a resistência. Só re-ouça depois do resumo. Fluxo antes de detalhe."},179:{dayName:"Dia 179 — Sexta-feira",title:"Último Dia de Preparação",focus:"Ritual final: revisão leve, 2 histórias e mente calma.",vocab:[{en:"Final",pt:"Final"},{en:"Prepare",pt:"Preparar"},{en:"Mentally",pt:"Mentalmente"},{en:"Relax",pt:"Relaxar"},{en:"Sleep",pt:"Dormir"},{en:"Hydrated",pt:"Hidratado"},{en:"Routine",pt:"Rotina"},{en:"Confident",pt:"Confiante"},{en:"Calm",pt:"Calmo"},{en:"Ready",pt:"Pronto"}],grammar:{title:"O Ritual do Dia Anterior",rule:"1) Revisão LEVE de 30 min (mapa dos tempos + 3 condicionais). 2) Repita suas 2 histórias (sucesso e superação) 3 vezes em voz alta. 3) Pratique as 10 perguntas clássicas. 4) NADA novo hoje — seu cérebro só reforça. 5) Durma 8 horas: a consolidação acontece no sono.",table:[{form:"Revisão leve",example:"I reviewed the time map one more time.",pt:"Revisei o mapa dos tempos mais uma vez."},{form:"Histórias",example:"I repeated my two stories out loud.",pt:"Repeti minhas duas histórias em voz alta."},{form:"Sono",example:"I will sleep eight hours tonight.",pt:"Vou dormir oito horas esta noite."}]},reading:{title:"The Night Before",text:"Tomorrow is the grand final test. Today, I am calm on purpose. I reviewed the time map for 30 minutes — light and happy. I repeated my two stories three times: the success story and the comeback story. Then, the classic questions, like a warm-up, not a marathon. And tonight? Eight hours of sleep, a glass of water by the bed, and my notebook with the key chunks. Nothing new today. Everything is already inside me. Tomorrow, I will simply show what I have built for 179 days.",translation:"Amanhã é o grande teste final. Hoje, estou calmo de propósito. Revisei o mapa dos tempos por 30 minutos — leve e feliz. Repeti minhas duas histórias três vezes: a de sucesso e a de superação. Depois, as perguntas clássicas, como aquecimento, não maratona. E esta noite? Oito horas de sono, um copo de água ao lado da cama e meu caderno com os chunks-chave. Nada novo hoje. Tudo já está dentro de mim. Amanhã, simplesmente mostrarei o que construí por 179 dias."},quiz:[{q:"Ritual:",options:["I reviewed the time map one more time.","I study everything new tonight.","I panic and watch series all night."],ans:"I reviewed the time map one more time."},{q:"Histórias:",options:["I repeated my two stories out loud.","I think about my stories.","My stories, I remember."],ans:"I repeated my two stories out loud."},{q:"Complete: 'I ___ sleep eight hours tonight.'",options:["will","would","did"],ans:"will"}],chunks:[{en:"tomorrow is the grand final test",pt:"amanhã é o grande teste final"},{en:"I repeated my two stories out loud",pt:"repeti minhas duas histórias em voz alta"},{en:"everything is already inside me",pt:"tudo já está dentro de mim"}],listeningScript:"The night before! Light review: the time map. My two stories, three times. Classic questions as a warm-up. Tonight: eight hours of sleep. Nothing new. Everything is inside me. Ready!",speakingPrompt:"Fale seu ritual: 'Today I reviewed... I repeated... Tonight I will... Tomorrow I will...'",lightReading:"Elite performers taper before the event: no new content, only consolidation — the night before is for confidence, not for information.",journalPrompt:"Today is Day 179. I am calm and ready for the final test.",tip:"DICA FINAL: mentalize o AMANHÃ em voz alta: 'Tomorrow I will read the text, answer the questions, and show my English.' Visualizar o processo reduz a ansiedade em 50%."},180:{dayName:"Dia 180 — Sábado",title:"TESTE FINAL B1 — O Grande Dia",focus:"Completar o teste abrangente do nível B1 e celebrar.",vocab:[{en:"Final test",pt:"Teste final"},{en:"Journey",pt:"Jornada"},{en:"Achievement",pt:"Conquista"},{en:"Milestone",pt:"Marco"},{en:"Certified",pt:"Certificado"},{en:"Ready",pt:"Pronto"},{en:"Proud",pt:"Orgulhoso"},{en:"Future",pt:"Futuro"},{en:"Consistent",pt:"Constante"},{en:"Bilingual",pt:"Bilíngue"}],grammar:{title:"O Teste Completo do B1",rule:"O texto final mistura TUDO: present, past, future, perfects, condicionais e voz passiva. Sua missão: identificar cada estrutura com as âncoras e responder com precisão. Você já treinou cada uma delas 100 vezes. Este dia é a celebração do treino.",table:[{form:"Perfect",example:"I have completed 180 days of practice.",pt:"Completei 180 dias de prática."},{form:"Condicional",example:"If I hadn't practiced daily, I wouldn't be here.",pt:"Se não tivesse praticado diariamente, não estaria aqui."},{form:"Passiva",example:"Every lesson was built for your journey.",pt:"Cada lição foi construída para a sua jornada."}]},reading:{title:"The Final Letter",text:"Dear me, today is the final test. I have completed 180 days of consistent practice. Every lesson was built for this moment. Last year, I couldn't say a full sentence; today, I can tell stories, negotiate, and explain code. If I hadn't practiced daily, I wouldn't be here. The perfect tenses are mine: I have learned, I have been studying, I have grown. The conditionals are mine: if I were you, I would be proud too. The passive is mine: lessons were learned, milestones were reached. Now, the door is open. The next chapters will be written in English.",translation:"Querido eu, hoje é o teste final. Completei 180 dias de prática constante. Cada lição foi construída para este momento. Ano passado, eu não conseguia dizer uma frase completa; hoje, posso contar histórias, negociar e explicar código. Se eu não tivesse praticado diariamente, não estaria aqui. Os perfects são meus: aprendi, venho estudando, cresci. Os condicionais são meus: se eu fosse você, também teria orgulho. A passiva é minha: lições foram aprendidas, marcos foram alcançados. Agora, a porta está aberta. Os próximos capítulos serão escritos em inglês."},quiz:[{q:"Perfect no texto:",options:["I have completed 180 days of practice.","I complete 180 days of practice.","I completed practice 180 days ago."],ans:"I have completed 180 days of practice."},{q:"Condicional no texto:",options:["If I hadn't practiced daily, I wouldn't be here.","If I don't practice, I am not here.","If I won't practice, I be here."],ans:"If I hadn't practiced daily, I wouldn't be here."},{q:"Passiva no texto:",options:["Every lesson was built for this moment.","They built every lesson.","Build lesson for moment."],ans:"Every lesson was built for this moment."}],chunks:[{en:"I have completed 180 days of practice",pt:"completei 180 dias de prática"},{en:"if I hadn't practiced daily, I wouldn't be here",pt:"se não tivesse praticado diariamente, não estaria aqui"},{en:"the next chapters will be written in English",pt:"os próximos capítulos serão escritos em inglês"}],listeningScript:"Day 180! The final test! I have completed 180 days of consistent practice. Lessons were learned, milestones were reached. If I hadn't practiced, I wouldn't be here. The door is open. The next chapters will be written in English. Congratulations!",speakingPrompt:"Grave seu discurso final: '180 days ago, I... Today, I can... Lessons were learned... Next, I will... Thank you to my past self.'",lightReading:"180 days is a 5% rule: show up daily and let time do the heavy lifting. You didn't become fluent in a day — you became fluent in 180 days of showing up.",journalPrompt:"Today is Day 180. I have COMPLETED the B1 final test and my 180-day journey!",tip:"CELEBRAÇÃO: escreva uma carta para o 'você do dia 1' e uma para o 'você do dia 360'. A jornada termina, mas a imersão é para sempre: próximo capítulo, B2 — em inglês, claro."}},a=[{id:24,title:"Semana 24 — Reta Final: Entrevistas & Teste B1",daysRange:"Dias 161 a 180",subtitle:"Teste Final B1, Entrevistas e Gramática Completa",badgeClass:"badge-red",grammar:["Entrevistas: apresentação, perguntas comuns e método STAR","Perguntas comportamentais e negociação salarial","Entrevista técnica: explicando código e portfólio","Simulados completos de entrevista","Revisão final: todos os tempos, condicionais e voz passiva"],vocab:"Entrevistas, negociação, cultura de empresa e revisão total",reading:"Anúncios de vagas, e-mails profissionais e textos mistos finais",listening:"Entrevistas reais e podcasts em velocidade natural",speaking:"Simulados de entrevista e maratonas finais de speaking",techBridge:"Entrevistas técnicas, portfólio em inglês e negociação salarial",saturday:{recall:[["tell me about yourself","fale sobre você"],["I'm a developer with four years of experience","sou desenvolvedor com quatro anos de experiência"],["why do you want to work here?","por que você quer trabalhar aqui?"],["I admire your culture and focus on quality","admiro sua cultura e o foco em qualidade"],["I am responsible for the backend of three products","sou responsável pelo backend de três produtos"],["last year, our system was slow","ano passado, nosso sistema era lento"],["the page now loads 60% faster","a página agora carrega 60% mais rápido"],["I can be too careful with details","posso ser detalhista demais"],["since then, I have learned to balance quality and speed","desde então, aprendi a equilibrar qualidade e velocidade"],["based on my research, the market range is 9-11k","com base na minha pesquisa, a faixa de mercado é 9-11k"],["is the salary flexible?","o salário é flexível?"],["when can I expect the next steps?","quando posso esperar os próximos passos?"]],reading:{title:"The Second Interview",text:"I received an invitation for a second interview! This time, the technical part comes first. The interviewer asked: 'Walk me through your best project.' I used my structure: 'This app is built with React and Node. The data is stored in PostgreSQL. I chose this because it separates the layers. If I had more time, I would add offline mode.' Then she asked a behavioral question: 'Tell me about a time you failed.' I answered honestly: 'Last year, I missed a deadline because I planned poorly. Since then, I have learned to break tasks into small pieces.' She smiled. Honesty with growth is power.",questions:["What comes first in the second interview?","How is the app built?","Why did the writer choose this architecture?","What would the writer add with more time?","Why did the writer miss a deadline last year, and what did they learn?"]},listening:"Listen: 'Second interview! Walk me through your best project. The app is built with React and Node. Data is stored in PostgreSQL. If I had more time, offline mode. A failure? I missed a deadline once. Since then, I break tasks into pieces!'",speaking:"Grave: apresentação + 1 STAR + 1 fraqueza + 3 perguntas para o entrevistador."}}];export{e as d,a as w};
